inline bool isKnownV3Topic(uint8_t topic) {
  return topic <= V3TopicControl;
}

inline bool isKnownV3MessageKind(uint8_t messageKind) {
  return messageKind <= V3Advertisement;
}

inline bool isAuthorityMessageKind(uint8_t messageKind) {
  return messageKind == V3Heartbeat
      || messageKind == V3Claim
      || messageKind == V3State
      || messageKind == V3Release
      || messageKind == V3Definition
      || messageKind == V3Schedule;
}

// Validate the common envelope before any topic-specific code may inspect its body.
inline bool isValidV3Envelope(const V3TopicEnvelope& envelope) {
  if (envelope.topicVersion == 0 || envelope.bodyLength > TUBES_V3_BODY_SIZE)
    return false;
  if (!isKnownV3MessageKind(envelope.messageKind))
    return false;
  if (isAuthorityMessageKind(envelope.messageKind) && envelope.authorityId == 0)
    return false;
  return true;
}

inline bool hasExactV3BodyLength(const V3TopicEnvelope& envelope, uint8_t expected) {
  return envelope.bodyLength == expected;
}

// Reject malformed known-topic bodies at ingress while leaving unknown topics skippable.
inline bool isValidKnownV3Body(uint8_t topic, const V3TopicPayload& payload) {
  const V3TopicEnvelope& envelope = payload.envelope;
  if (!isKnownV3Topic(topic))
    return true;
  if (envelope.topicVersion != TUBES_TOPIC_VERSION_1)
    return false;

  // Presence is advisory state, never an authority claim or heartbeat.
  if (topic == V3TopicPresence && envelope.messageKind != V3State)
    return false;

  if (envelope.messageKind == V3Claim
      || envelope.messageKind == V3Release
      || envelope.messageKind == V3Heartbeat)
    return envelope.bodyLength == 0;

  switch (topic) {
    case V3TopicPresence:
      return envelope.messageKind == V3State
          && hasExactV3BodyLength(envelope, sizeof(V3PresencePayload));
    case V3TopicBeat:
      return envelope.messageKind == V3State
          && hasExactV3BodyLength(envelope, sizeof(V3BeatPayload));
    case V3TopicPattern:
      return envelope.messageKind == V3State
          && hasExactV3BodyLength(envelope, sizeof(V3PatternPayload));
    case V3TopicPalette:
      return (envelope.messageKind == V3Definition
              && (hasExactV3BodyLength(envelope, sizeof(V3Palette16Definition))
                  || hasExactV3BodyLength(envelope, sizeof(V3GradientPaletteDefinition))))
          || (envelope.messageKind == V3Schedule
              && hasExactV3BodyLength(envelope, sizeof(V3PaletteSchedulePayload)));
    case V3TopicEffect:
      return envelope.messageKind == V3State
          && hasExactV3BodyLength(envelope, sizeof(V3EffectPayload));
    case V3TopicPosition:
      return (envelope.messageKind == V3State
              && hasExactV3BodyLength(envelope, sizeof(V3PositionFramePayload)))
          || (envelope.messageKind == V3Advertisement
              && hasExactV3BodyLength(envelope, sizeof(V3PositionAdvertisementPayload)));
    case V3TopicDebug:
      return envelope.messageKind == V3State
          && hasExactV3BodyLength(envelope, sizeof(V3DebugPayload));
    case V3TopicControl: {
      if (envelope.messageKind != V3State || envelope.bodyLength < 2)
        return false;
      const V3ControlPayload& control = *reinterpret_cast<const V3ControlPayload*>(payload.body);
      return control.commandLength <= sizeof(control.commandData)
          && envelope.bodyLength == uint8_t(control.commandLength + 2);
    }
    default:
      return true;
  }
}

inline bool isValidV3TopicPayload(uint8_t topic, const V3TopicPayload& payload) {
  return isValidV3Envelope(payload.envelope) && isValidKnownV3Body(topic, payload);
}

// Copy a validated fixed-size value from the bounded body without relying on alignment.
template<typename T>
inline bool readV3Body(const V3TopicPayload& payload, T& value) {
  if (payload.envelope.bodyLength != sizeof(T) || sizeof(T) > sizeof(payload.body))
    return false;
  memcpy(&value, payload.body, sizeof(T));
  return true;
}

// Build a zero-filled topic payload so reserved bytes never leak stack contents.
inline bool writeV3Body(V3TopicPayload& payload, const void* body, uint8_t bodyLength) {
  if (bodyLength > sizeof(payload.body) || (bodyLength > 0 && body == nullptr))
    return false;
  memset(payload.body, 0, sizeof(payload.body));
  if (bodyLength > 0)
    memcpy(payload.body, body, bodyLength);
  payload.envelope.bodyLength = bodyLength;
  return true;
}

